    case imageAnchorDetected = "image_anchor_detected"
    case interruptionBegan = "interruption_began"
    case interruptionEnded = "interruption_ended"
    case memoryWarning = "memory_warning"
    case motionUnavailable = "motion_unavailable"
    case recordingClosed = "recording_closed"
    case recordingOpened = "recording_opened"
    case relocalizationBegan = "relocalization_began"
    case relocalizationEnded = "relocalization_ended"
    case screenCaptureBegan = "screen_capture_began"
    case screenCaptureEnded = "screen_capture_ended"
