    /// What native code returned, as JSON text, or null for nothing or for a binary result
    /// (which only boundary/<seq>.f32 holds).
    let result: String?
    /// When native code answered the call.
    let t: Double

    enum CodingKeys: String, CodingKey {
        case args = "args"
        case call = "call"
        case error = "error"
        case result = "result"
        case t = "t"
    }
}

