enum ThermalState: String, Codable, Equatable, Sendable {
    case critical = "critical"
    case fair = "fair"
    case nominal = "nominal"
    case serious = "serious"
}

/// One line of mesh/history.jsonl in a session recording, recording_version 1
/// (docs/session-recording.md): the index of one block of mesh/history.bin. The first
/// snapshot, when the recording opens, writes every mesh anchor as add; later snapshots
/// write anchors whose geometry changed; the final snapshot, when it closes with end_anchor
/// or idle (unless the no_mesh_history step was reached), writes every mesh anchor with
/// final true at window.end_t. Checked by validate-recording, not by this schema: t never
/// decreases; an anchor's first line is an add; transform, offset, bytes, vertices and faces
/// are null exactly for remove; each block lies inside history.bin; and capture_id is set
/// only on final lines.
struct MeshHistoryLine: Codable, Equatable, Sendable {
    /// The mesh anchor's identifier.
    let anchor: String
    /// The block's length in history.bin (compressed), or null for remove.
    let bytes: Int?
    /// On a final snapshot, the segment whose session-end reads it is (the segment open when it
    /// was taken), or null when no segment was open; null on other lines.
    let captureID: String?
    /// Faces in the block, or null for remove.
    let faces: Int?
    /// true for a final snapshot, which holds every mesh anchor with the transforms read at that
    /// moment.
    let meshHistoryLineFinal: Bool
    /// Where the block starts in history.bin, or null for remove.
    let offset: Int?
    let op: HistoryOp
    /// The snapshot's time.
    let t: Double
    /// Anchor to world at t, or null for remove.
    let transform: [Double]?
    /// Vertices in the block, or null for remove.
    let vertices: Int?

    enum CodingKeys: String, CodingKey {
        case anchor = "anchor"
        case bytes = "bytes"
        case captureID = "capture_id"
        case faces = "faces"
        case meshHistoryLineFinal = "final"
        case offset = "offset"
        case op = "op"
        case t = "t"
        case transform = "transform"
        case vertices = "vertices"
    }
}

/// parts.json of a replay set's export, recording_version 1 (docs/session-recording.md):
/// written by exportRecording beside the parts in Documents/exports/replay-<recording_id>/;
/// pnpm rec pull copies only the parts it lists. Checked by the PC tools, not by this
/// schema: the names run 0000.part, 0001.part and so on without gaps, every part but the
/// last is UPLOAD_PART_BYTES long, and the bytes add up to tar_bytes.
struct ExportParts: Codable, Equatable, Sendable {
    /// The parts in order. At most 4096 (DEFAULT_RECORDING_LIMITS.maxExportParts, 64 GiB in 16
    /// MiB parts).
    let parts: [ExportPart]
    /// The recording's id (or the session's, for an unrecorded session).
    let recordingID: String
    /// Version of the session recording format.
    let recordingVersion: Int
    /// Size of the whole tar in bytes.
    let tarBytes: Int
    /// SHA-256 of the whole tar.
    let tarSha256: String

    enum CodingKeys: String, CodingKey {
        case parts = "parts"
        case recordingID = "recording_id"
        case recordingVersion = "recording_version"
        case tarBytes = "tar_bytes"
        case tarSha256 = "tar_sha256"
    }
}

/// One part of the export tar.
struct ExportPart: Codable, Equatable, Sendable {
    /// Size in bytes, at most UPLOAD_PART_BYTES.
    let bytes: Int
    /// The part's file name: four digits, then .part.
    let name: String
    /// SHA-256 of the part's bytes.
    let sha256: String

    enum CodingKeys: String, CodingKey {
        case bytes = "bytes"
        case name = "name"
        case sha256 = "sha256"
    }
}

